// GENERATED by scripts/sync-wrfm.mjs from wrfm-source/src/utils/broadcastSchedule.js - do not edit here; edit WRFM and re-sync.
// ─────────────────────────────────────────────────────────────────────────────
// broadcastSchedule.js — deterministic live broadcast timeline for WRFM.
//
// Every listener computes the same schedule from the wall clock alone: the
// timeline is an infinite sequence of "blocks" generated by a seeded PRNG from
// a fixed anchor date, using exact per-file durations (audioDurations.json).
// At any instant, getLiveNow() returns which segment is on air and how far in.
// No server needed — two people in different time zones hear the same moment.
//
// Interstitial selection uses "station time" (fixed UTC-5) so time-of-day
// flavored chatter stays deterministic worldwide.
// ─────────────────────────────────────────────────────────────────────────────

import songs from "./wrfm_songs.json";
import station from "./wrfm_station.json";
import chatterExt from "./wrfm_chatter_extension.json";
import DURATIONS from "./audioDurations.json";

// Fixed anchor — never change this once live, or everyone "time-jumps".
const ANCHOR_MS = Date.parse("2026-08-08T00:00:00Z");
const STATION_UTC_OFFSET_HOURS = -5; // WRFM broadcasts on East Coast time

// ---------- seeded PRNG (mulberry32) ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function seededShuffle(arr, rng) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---------- pools (stable order: sorted by id so every client agrees) ----------
const SONG_POOL = songs
  .filter((s) => s.asset?.cid && DURATIONS[s.asset.cid])
  .map((s) => ({ type: "song", id: s.id, cid: s.asset.cid, dur: DURATIONS[s.asset.cid] }))
  .sort((a, b) => (a.id < b.id ? -1 : 1));

const ALL_CHATTER = [...(station.chatter || []), ...(chatterExt.clips || [])];
const CHATTER_POOL = ALL_CHATTER
  .filter((c) => c.asset?.cid && DURATIONS[c.asset.cid] && c.category !== "hourly_id")
  .map((c) => ({
    type: "clip", id: c.id, cid: c.asset.cid, dur: DURATIONS[c.asset.cid],
    category: c.category || "chatter",
    buckets: c.conditions?.timeBucketsAnyOf || null,
    clip: c, // original clip object (RadioCallOverlay reads speaker/tags from it)
  }))
  .sort((a, b) => (a.id < b.id ? -1 : 1));

const COMM_POOL = (station.commercials || [])
  .filter((c) => c.enabled !== false && c.asset?.cid && DURATIONS[c.asset.cid])
  .map((c) => ({
    type: "clip", id: c.id, cid: c.asset.cid, dur: DURATIONS[c.asset.cid],
    category: "commercial", buckets: c.timeBuckets || null, clip: c,
  }))
  .sort((a, b) => (a.id < b.id ? -1 : 1));

// ---------- station-time bucket (deterministic worldwide) ----------
export function stationBucket(atMs) {
  const h = (24 + new Date(atMs).getUTCHours() + STATION_UTC_OFFSET_HOURS) % 24;
  if (h >= 5 && h < 12) return "morning";
  if (h >= 12 && h < 17) return "afternoon";
  if (h >= 17 && h < 22) return "evening";
  if (h >= 22 || h < 2) return "late";
  return "graveyard";
}

// ---------- channels ----------
// "main"      — WRFM 97.1, programmed to the station clock
// "afterdark" — the late-night feed on demand, also synced across listeners
export const CHANNELS = ["main", "afterdark"];

// True night exclusives: hushed, lore-heavy clips that only make sense at 2am.
// They never air on the main channel outside graveyard hours — visiting late
// (or tuning to After Dark) is how you find them.
const NIGHT_EXCLUSIVE = new Set([
  "special_001",     // rare lore
  "post_010",        // graveyard, quiet
  "post_005",        // intimate
  "post_004",        // calm, late
  "pre_001",         // late, intimate
  "pre_004",         // introspective
  "pre_010",         // introspective, late
  "vera_ident_004",  // intimate
  "vera_ident_005",  // noir
]);

const bucketFor = (channel, atMs) =>
  channel === "afterdark" ? "late" : stationBucket(atMs);

/** Weighted pick: time-appropriate clips are preferred, not enforced — so a
 *  daytime listener still meets the callers and PSAs that used to be locked
 *  to the night. Night exclusives stay behind the after-hours gate. */
function pickFromPool(pool, rng, atMs, channel) {
  if (pool.length === 0) return null;
  const bucket = bucketFor(channel, atMs);
  const nightMode = channel === "afterdark" || bucket === "late" || bucket === "graveyard";

  const scored = [];
  let total = 0;
  for (const c of pool) {
    if (NIGHT_EXCLUSIVE.has(c.id) && !nightMode) continue;
    const fits = !c.buckets || c.buckets.includes(bucket);
    let w = fits ? 3 : 1;
    // Callers and special events are the memorable bits — make sure a short
    // visit at any hour has a real chance of hearing one.
    if (c.category === "special_event" || c.category === "caller") w *= 2;
    scored.push([c, w]);
    total += w;
  }
  if (scored.length === 0) return null;

  let roll = rng() * total;
  for (const [c, w] of scored) {
    roll -= w;
    if (roll <= 0) return c;
  }
  return scored[scored.length - 1][0];
}

// ---------- block generation ----------
// A block = one seeded shuffle through the whole song library with chatter and
// commercial breaks woven in every 2-4 songs (~3.5 hours of programming).
// Each channel keeps its own cache and its own seed salt, so the two channels
// are genuinely different programs — not the same records in the same order.
const CHANNEL_SALT = { main: 0x97f1, afterdark: 0x5b3d };
const channelState = {
  main: { cache: new Map(), starts: [ANCHOR_MS] },
  afterdark: { cache: new Map(), starts: [ANCHOR_MS] },
};
const stateFor = (channel) => channelState[channel] || channelState.main;

function buildBlock(index, blockStartMs, channel) {
  const st = stateFor(channel);
  const cached = st.cache.get(index);
  if (cached) return cached;

  const rng = mulberry32((CHANNEL_SALT[channel] || CHANNEL_SALT.main) ^ (index * 2654435761));
  const order = seededShuffle(SONG_POOL, rng);
  const segments = [];
  let elapsed = 0;
  let untilBreak = 2 + Math.floor(rng() * 3); // 2-4 songs between interstitials

  for (const song of order) {
    segments.push(song);
    elapsed += song.dur;
    untilBreak--;
    if (untilBreak <= 0) {
      const atMs = blockStartMs + elapsed * 1000;
      // 60% Vera chatter, 40% commercial spot
      const pool = rng() < 0.6 ? CHATTER_POOL : COMM_POOL;
      const clip = pickFromPool(pool, rng, atMs, channel);
      if (clip) {
        segments.push(clip);
        elapsed += clip.dur;
      }
      untilBreak = 2 + Math.floor(rng() * 3);
    }
  }

  const block = { segments, totalDur: elapsed };
  st.cache.set(index, block);
  return block;
}

// Block start times are cumulative, so we memoize them as we walk forward.
function blockStartMs(index, channel) {
  const st = stateFor(channel);
  while (st.starts.length <= index) {
    const i = st.starts.length - 1;
    const b = buildBlock(i, st.starts[i], channel);
    st.starts.push(st.starts[i] + b.totalDur * 1000);
  }
  return st.starts[index];
}

// ---------- public API ----------

/** What is on air right now?
 *  Returns { segment, offset, blockIndex, segIndex, startedAt } or null. */
export function getLiveNow(nowMs = Date.now(), channel = "main") {
  if (SONG_POOL.length === 0) return null;
  if (nowMs < ANCHOR_MS) nowMs = ANCHOR_MS;

  // Find the block containing nowMs
  let i = 0;
  while (blockStartMs(i + 1, channel) <= nowMs) i++;

  const block = buildBlock(i, blockStartMs(i, channel), channel);
  let t = (nowMs - blockStartMs(i, channel)) / 1000;
  for (let s = 0; s < block.segments.length; s++) {
    const seg = block.segments[s];
    if (t < seg.dur) {
      return {
        segment: seg,
        offset: t,
        blockIndex: i,
        segIndex: s,
        channel,
        startedAt: nowMs - t * 1000,
      };
    }
    t -= seg.dur;
  }
  // Numerical edge: fell off the end — return start of next block
  const nb = buildBlock(i + 1, blockStartMs(i + 1, channel), channel);
  return { segment: nb.segments[0], offset: 0, blockIndex: i + 1, segIndex: 0, channel, startedAt: blockStartMs(i + 1, channel) };
}

/** The next few segments coming up (for "up next" UI). */
export function getUpNext(count = 3, nowMs = Date.now(), channel = "main") {
  const now = getLiveNow(nowMs, channel);
  if (!now) return [];
  const out = [];
  let { blockIndex, segIndex } = now;
  while (out.length < count) {
    segIndex++;
    let block = buildBlock(blockIndex, blockStartMs(blockIndex, channel), channel);
    if (segIndex >= block.segments.length) {
      blockIndex++; segIndex = 0;
      block = buildBlock(blockIndex, blockStartMs(blockIndex, channel), channel);
    }
    out.push(block.segments[segIndex]);
  }
  return out;
}
